insert into public.tasks (id, lesson_id, sort, kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data) values ('00000000-0000-4000-8000-000000200050', '00000000-0000-4000-8000-000000001006', 1, 'quiz', 'Unit 1 checkpoint', 'Unit 1 checkpoint', 'Unit 1 checkpoint', 'Choose the best answer. Review each explanation after submitting.', 'Choose the best answer. Review each explanation after submitting.', 'Choose the best answer. Review each explanation after submitting.', '{"questions":[{"question":"She ___ yoga every morning.","options":["do","does","goes"],"correct":1,"explanation":"She takes does with the activity yoga.","explanation_en":"She takes does with the activity yoga."},{"question":"___ you play any sports?","options":["Do","Does","Are"],"correct":0,"explanation":"Use do with you and a main verb.","explanation_en":"Use do with you and a main verb."},{"question":"How often ___ your brother go swimming?","options":["do","does","is"],"correct":1,"explanation":"Use does with a singular third-person subject.","explanation_en":"Use does with a singular third-person subject."},{"question":"We ___ watch sport on TV.","options":["don’t","doesn’t","aren’t"],"correct":0,"explanation":"Use do not with we.","explanation_en":"Use do not with we."},{"question":"Choose the correct sentence.","options":["I usually stay in on Mondays.","I stay usually in on Mondays.","I usually stays in on Mondays."],"correct":0,"explanation":"Usually comes before the main verb.","explanation_en":"Usually comes before the main verb."},{"question":"Choose the correct negative.","options":["He doesn’t likes football.","He doesn’t like football.","He don’t like football."],"correct":1,"explanation":"After does not, use the base verb.","explanation_en":"After does not, use the base verb."},{"question":"Choose the correct question.","options":["Do you interested in music?","Are you interested in music?","Does you interested in music?"],"correct":1,"explanation":"Interested takes be.","explanation_en":"Interested takes be."},{"question":"Twice a week means …","options":["every two weeks","two times each week","every day"],"correct":1,"explanation":"Twice means two times.","explanation_en":"Twice means two times."},{"question":"I ___ photos of buildings.","options":["take","do","play"],"correct":0,"explanation":"The phrase is take photos.","explanation_en":"The phrase is take photos."},{"question":"A useful follow-up to “I go cycling” is …","options":["Where do you go cycling?","Where you cycling?","Where does you go?"],"correct":0,"explanation":"Ask for more detail with a correctly formed question.","explanation_en":"Ask for more detail with a correctly formed question."}]}'::jsonb) on conflict do nothing;
