insert into public.tasks (id, lesson_id, sort, kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data) values ('00000000-0000-4000-8000-000000200110', '00000000-0000-4000-8000-000000001012', 1, 'quiz', 'Unit 2 checkpoint', 'Unit 2 checkpoint', 'Unit 2 checkpoint', 'Choose the best answer. Review each explanation after submitting.', 'Choose the best answer. Review each explanation after submitting.', 'Choose the best answer. Review each explanation after submitting.', '{"questions":[{"question":"Yesterday I ___ a new club.","options":["join","joined","joining"],"correct":1,"explanation":"Yesterday signals a completed past event.","explanation_en":"Yesterday signals a completed past event."},{"question":"We ___ home early.","options":["didn’t went","didn’t go","don’t went"],"correct":1,"explanation":"Use the base form after did not.","explanation_en":"Use the base form after did not."},{"question":"___ you enjoy the class?","options":["Did","Were","Does"],"correct":0,"explanation":"Use did for past questions with enjoy.","explanation_en":"Use did for past questions with enjoy."},{"question":"She ___ nervous before the lesson.","options":["were","was","did"],"correct":1,"explanation":"Use was with she.","explanation_en":"Use was with she."},{"question":"Choose the correct question.","options":["Did he took the bus?","Did he take the bus?","Does he took the bus?"],"correct":1,"explanation":"Use take after did.","explanation_en":"Use take after did."},{"question":"I met Sara ___ September.","options":["at","on","in"],"correct":2,"explanation":"Use in with months.","explanation_en":"Use in with months."},{"question":"We played football two days ___.","options":["last","ago","yesterday"],"correct":1,"explanation":"Ago follows the time period.","explanation_en":"Ago follows the time period."},{"question":"The past simple of feel is …","options":["feeled","felt","fallen"],"correct":1,"explanation":"Feel is irregular: felt.","explanation_en":"Feel is irregular: felt."},{"question":"Which ending adds a syllable?","options":["walked","played","wanted"],"correct":2,"explanation":"After /t/, -ed is pronounced /ɪd/.","explanation_en":"After /t/, -ed is pronounced /ɪd/."},{"question":"Choose the sentence giving a reason.","options":["I stayed home because I felt tired.","I stayed home but I felt tired.","I stayed home then I felt tired."],"correct":0,"explanation":"Because introduces the reason.","explanation_en":"Because introduces the reason."}]}'::jsonb) on conflict do nothing;
