insert into public.tasks (id, lesson_id, sort, kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data) values ('00000000-0000-4000-8000-000000200170', '00000000-0000-4000-8000-000000001018', 1, 'quiz', 'Unit 3 checkpoint', 'Unit 3 checkpoint', 'Unit 3 checkpoint', 'Choose the best answer. Review each explanation after submitting.', 'Choose the best answer. Review each explanation after submitting.', 'Choose the best answer. Review each explanation after submitting.', '{"questions":[{"question":"You ___ prepare your bag earlier.","options":["should","should to","shoulds"],"correct":0,"explanation":"Should is followed by the base verb.","explanation_en":"Should is followed by the base verb."},{"question":"She ___ wear a badge at work.","options":["have to","has to","have"],"correct":1,"explanation":"Use has to with she.","explanation_en":"Use has to with she."},{"question":"The course is optional. You …","options":["don’t have to attend","can’t attend","have to attend"],"correct":0,"explanation":"Do not have to means it is not required.","explanation_en":"Do not have to means it is not required."},{"question":"Phones are forbidden here. You …","options":["can’t use one","don’t have to use one","can use one"],"correct":0,"explanation":"Cannot expresses the prohibition.","explanation_en":"Cannot expresses the prohibition."},{"question":"___ he have to work on Saturdays?","options":["Does","Has","Is"],"correct":0,"explanation":"Use does + subject + have to.","explanation_en":"Use does + subject + have to."},{"question":"Choose the correct sentence.","options":["I can to use a computer.","I can use a computer.","I can uses a computer."],"correct":1,"explanation":"Can is followed by the base verb.","explanation_en":"Can is followed by the base verb."},{"question":"Choose the correct advice.","options":["You shouldn’t works during your break.","You shouldn’t work during your break.","You shouldn’t to work during your break."],"correct":1,"explanation":"Use the base verb after should not.","explanation_en":"Use the base verb after should not."},{"question":"Who welcomes hotel guests?","options":["a receptionist","a gardener","a delivery driver"],"correct":0,"explanation":"Welcoming guests is a receptionist’s duty.","explanation_en":"Welcoming guests is a receptionist’s duty."},{"question":"I usually ___ a break at eleven.","options":["take","do","make"],"correct":0,"explanation":"The phrase is take a break.","explanation_en":"The phrase is take a break."},{"question":"Advice about forgotten deadlines:","options":["You should use a calendar.","You should to use a calendar.","You has to calendar."],"correct":0,"explanation":"Should + base verb gives a suggestion.","explanation_en":"Should + base verb gives a suggestion."}]}'::jsonb) on conflict do nothing;
insert into public.tasks (id, lesson_id, sort, kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data) values ('00000000-0000-4000-8000-000000200171', '00000000-0000-4000-8000-000000001018', 2, 'writing', 'Your writing', 'Your writing', 'Your writing', 'Write an 80–100 word message to a friend about a fictional new job: schedule, duties, two rules, something optional and how you plan your rest time. Use a separate final sentence to give your friend one practical suggestion with should.', 'Write an 80–100 word message to a friend about a fictional new job: schedule, duties, two rules, something optional and how you plan your rest time. Use a separate final sentence to give your friend one practical suggestion with should.', 'Write an 80–100 word message to a friend about a fictional new job: schedule, duties, two rules, something optional and how you plan your rest time. Use a separate final sentence to give your friend one practical suggestion with should.', '{"min_words":80,"max_words":100,"checklist":["I completed the task.","I checked the target grammar.","I used phrases from this unit."]}'::jsonb) on conflict do nothing;
insert into public.lessons (id, course_id, sort, summary, summary_kk, summary_en, minutes, is_free, is_published, title, title_kk, title_en) values ('00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000100', 101, 'Когда вы в последний раз пробовали что-то новое?', 'Соңғы рет қашан жаңа нәрсені байқап көрдіңіз?', 'When did you last try something new?', 5, true, false, 'Start here', 'Бастайық', 'Start here') on conflict do nothing;
insert into public.lesson_materials (lesson_id, video_url, body, body_kk, body_en) values ('00000000-0000-4000-8000-000000000101', 'https://www.youtube.com/watch?v=UNP03fDSj1U', '## When did you last try something new?
В этом юните вы будете говорить о переменах в жизни, понимать чужие истории и расскажете свою.

Посмотрите короткое выступление: автор 30 дней подряд пробовал что-то новое. Попробуйте уловить главную мысль — детали разберём позже.', '## When did you last try something new?
Бұл бөлімде өмірдегі өзгерістер туралы сөйлейсіз, басқалардың әңгімелерін түсінесіз және өз әңгімеңізді айтасыз.

Қысқа баяндаманы көріңіз: автор 30 күн қатарынан жаңа нәрсе байқап көрген. Негізгі ойын ұстауға тырысыңыз — егжей-тегжейін кейін талдаймыз.', '## When did you last try something new?
In this unit you''ll talk about changes in life, understand other people''s stories and tell your own.

Watch a short talk: the speaker tried something new for 30 days in a row. Try to catch the main idea — we''ll look at the details later.') on conflict do nothing;
insert into public.tasks (kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data, id, lesson_id, sort) values ('writing', 'Разминка', 'Дайындық', 'Warm-up', 'Think of one thing you started recently. What made you begin? Напишите 2–3 предложения.', 'Think of one thing you started recently. What made you begin? 2–3 сөйлем жазыңыз.', 'Think of one thing you started recently. What made you begin? Write 2–3 sentences.', '{"min_words":15,"max_words":80,"checklist":[]}'::jsonb, '00000000-0000-4000-8000-000000010101', '00000000-0000-4000-8000-000000000101', 1) on conflict do nothing;
