insert into public.lesson_materials (lesson_id, video_url, body, body_kk, body_en) values ('00000000-0000-4000-8000-000000000102', '', '## Build your word power
Эти фразы помогут рассказать о новом опыте. Выучите их как готовые блоки — не по одному слову.', '## Build your word power
Бұл тіркестер жаңа тәжірибе туралы айтуға көмектеседі. Оларды жеке сөз емес, дайын блок ретінде жаттаңыз.', '## Build your word power
These phrases will help you talk about new experiences. Learn them as ready-made chunks — not word by word.') on conflict do nothing;
insert into public.tasks (kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data, id, lesson_id, sort) values ('vocabulary', 'Фразы юнита', 'Бөлім тіркестері', 'Unit phrases', 'Переверните карточку и повторите фразу вслух.', 'Карточканы аударып, тіркесті дауыстап қайталаңыз.', 'Flip the card and repeat the phrase out loud.', '{"words":[{"term":"settle in","ru":"освоиться на новом месте","kk":"жаңа ортаға үйрену","example":"It took me a month to settle in."},{"term":"get to know","ru":"познакомиться поближе","kk":"танысып-білу","example":"I got to know my colleagues at lunch."},{"term":"sign up","ru":"записаться","kk":"тіркелу","example":"She signed up for a photography walk."},{"term":"give something a try","ru":"попробовать что-то","kk":"бір нәрсені байқап көру","example":"Why not give yoga a try?"},{"term":"turning point","ru":"поворотный момент","kk":"бетбұрыс","example":"That evening was a turning point."},{"term":"step outside your comfort zone","ru":"выйти из зоны комфорта","kk":"үйреншікті ортадан шығу","example":"Speaking English helps me step outside my comfort zone."}]}'::jsonb, '00000000-0000-4000-8000-000000010201', '00000000-0000-4000-8000-000000000102', 1) on conflict do nothing;
insert into public.tasks (kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data, id, lesson_id, sort) values ('pronunciation', 'Фразы в речи', 'Сөйлеудегі тіркестер', 'Phrases in speech', 'Произнесите фразы целиком, с естественным ритмом.', 'Тіркестерді табиғи ырғақпен тұтас айтыңыз.', 'Say each phrase as a whole, with a natural rhythm.', '{"phrases":[{"text":"It took me a month to settle in.","hint":"settle in звучит слитно: settlin.","hint_kk":"settle in бірге айтылады: settlin.","hint_en":"settle in is linked together: settlin."},{"text":"Why not give it a try?","hint":"give it a — почти одно слово.","hint_kk":"give it a — бір сөз сияқты.","hint_en":"give it a — almost one word."},{"text":"That evening was a turning point.","hint":"Ударение на TURNing.","hint_kk":"Екпін TURNing-ке түседі.","hint_en":"The stress is on TURNing."}]}'::jsonb, '00000000-0000-4000-8000-000000010202', '00000000-0000-4000-8000-000000000102', 2) on conflict do nothing;
insert into public.lessons (id, course_id, sort, summary, summary_kk, summary_en, minutes, is_free, is_published, title, title_kk, title_en) values ('00000000-0000-4000-8000-000000000103', '00000000-0000-4000-8000-000000000100', 103, 'Past simple и past continuous в одной истории.', 'Бір әңгімедегі past simple және past continuous.', 'Past simple and past continuous in one story.', 15, false, false, 'Stories in progress', 'Өткен шақтағы оқиғалар', 'Stories in progress') on conflict do nothing;
insert into public.lesson_materials (lesson_id, video_url, body, body_kk, body_en) values ('00000000-0000-4000-8000-000000000103', '', '## Past simple + past continuous
- **Past continuous** — фоновое действие, которое длилось: **I was waiting for a bus.**
- **Past simple** — событие, которое его прервало: **I saw a poster.**

Вместе: **While I was waiting for a bus, I saw a poster.**

## Окончание -ed
У правильных глаголов -ed звучит тремя способами: **/t/** (noticed), **/d/** (learned), **/ɪd/** (started — после t и d).', '## Past simple + past continuous
- **Past continuous** — ұзаққа созылған фондық әрекет: **I was waiting for a bus.**
- **Past simple** — оны бөлген оқиға: **I saw a poster.**

Бірге: **While I was waiting for a bus, I saw a poster.**

## -ed жалғауы
Дұрыс етістіктерде -ed үш түрлі айтылады: **/t/** (noticed), **/d/** (learned), **/ɪd/** (started — t және d дыбыстарынан кейін).', '## Past simple + past continuous
- **Past continuous** — a background action that was in progress: **I was waiting for a bus.**
- **Past simple** — the event that interrupted it: **I saw a poster.**

Together: **While I was waiting for a bus, I saw a poster.**

## The -ed ending
In regular verbs, -ed is pronounced in three ways: **/t/** (noticed), **/d/** (learned), **/ɪd/** (started — after t and d).') on conflict do nothing;
insert into public.tasks (kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data, id, lesson_id, sort) values ('pronunciation', 'Окончание -ed', '-ed жалғауы', 'The -ed ending', 'Следите за последним звуком глагола.', 'Етістіктің соңғы дыбысына назар аударыңыз.', 'Pay attention to the last sound of the verb.', '{"phrases":[{"text":"I noticed that my self-confidence grew.","hint":"noticed — короткий глухой /t/, без лишнего слога.","hint_kk":"noticed — қысқа қатаң /t/, артық буынсыз.","hint_en":"noticed — a short voiceless /t/, no extra syllable."},{"text":"I learned that small changes stick.","hint":"learned — звонкий /d/.","hint_kk":"learned — ұяң /d/.","hint_en":"learned — a voiced /d/."},{"text":"As I started to do harder challenges, I grew more confident.","hint":"started — дополнительный слог: start-id.","hint_kk":"started — қосымша буын: start-id.","hint_en":"started — an extra syllable: start-id."}]}'::jsonb, '00000000-0000-4000-8000-000000010301', '00000000-0000-4000-8000-000000000103', 1) on conflict do nothing;
insert into public.tasks (kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data, id, lesson_id, sort) values ('quiz', 'Grammar practice', 'Grammar practice', 'Grammar practice', 'Выберите правильную форму.', 'Дұрыс форманы таңдаңыз.', 'Choose the correct form.', '{"questions":[{"question":"I ___ home when I ___ an old friend.","options":["walked / was seeing","was walking / saw","was walking / was seeing"],"correct":1,"explanation":"Фоновое действие — past continuous, событие — past simple.","explanation_kk":"Ұзақ әрекетке past continuous, оны бөлген оқиғаға past simple қолданылады.","explanation_en":"Background action — past continuous; the event — past simple."},{"question":"While Amina ___ dinner, the lights ___.","options":["made / were going out","was making / went out","made / went out"],"correct":1,"explanation":"Ужин уже готовился, когда погас свет.","explanation_kk":"Тамақ дайындау жүріп жатқанда жарық өшті.","explanation_en":"Dinner was already being made when the lights went out."},{"question":"Which sentence gives two actions in sequence?","options":["I opened the email and called my sister.","I was opening the email while I called.","I opened the email when I was call."],"correct":0,"explanation":"Для завершённых действий одно за другим — past simple.","explanation_kk":"Бірінен кейін бірі аяқталған әрекеттерге past simple қолданылады.","explanation_en":"For finished actions that happen one after another, use past simple."},{"question":"At 8 p.m. yesterday, we ___ for the train.","options":["waited","were waiting","was waiting"],"correct":1,"explanation":"Действие в процессе в конкретный момент прошлого — past continuous.","explanation_kk":"Белгілі бір өткен уақытта жүріп жатқан әрекет past continuous болады.","explanation_en":"An action in progress at a specific moment in the past — past continuous."}]}'::jsonb, '00000000-0000-4000-8000-000000010302', '00000000-0000-4000-8000-000000000103', 2) on conflict do nothing;
insert into public.lessons (id, course_id, sort, summary, summary_kk, summary_en, minutes, is_free, is_published, title, title_kk, title_en) values ('00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000100', 104, 'Читаем историю Даны: что изменило её планы?', 'Дананың әңгімесін оқимыз: оның жоспарын не өзгертті?', 'Read Dana''s story: what changed her plans?', 15, false, false, 'A new beginning', 'Жаңа бастама', 'A new beginning') on conflict do nothing;
insert into public.lesson_materials (lesson_id, video_url, body, body_kk, body_en) values ('00000000-0000-4000-8000-000000000104', '', '## One decision, a new direction
Прочитайте короткую историю и ответьте на вопросы.

Last spring, Dana was working in a busy office in Astana. She liked her colleagues, but she felt that every day was the same. One evening, while she was waiting for a bus, she saw a poster for a weekend photography walk.

Dana nearly walked past it. Then she remembered the camera her grandfather had given her and signed up. During the walk, she met people who saw the city in a completely different way. Six months later, she still works at the same office — but now she also photographs local events. That rainy evening became a small turning point.', '', '## One decision, a new direction
Read the short story and answer the questions.

Last spring, Dana was working in a busy office in Astana. She liked her colleagues, but she felt that every day was the same. One evening, while she was waiting for a bus, she saw a poster for a weekend photography walk.

Dana nearly walked past it. Then she remembered the camera her grandfather had given her and signed up. During the walk, she met people who saw the city in a completely different way. Six months later, she still works at the same office — but now she also photographs local events. That rainy evening became a small turning point.') on conflict do nothing;
insert into public.tasks (kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data, id, lesson_id, sort) values ('quiz', 'Reading check', 'Reading check', 'Reading check', 'Ответьте по тексту.', 'Мәтін бойынша жауап беріңіз.', 'Answer based on the text.', '{"questions":[{"question":"Why did Dana notice the photography poster?","options":["She was looking for a new job.","She saw it while waiting for a bus.","Her colleague showed it to her."],"correct":1,"explanation":"В тексте: she saw the poster while she was waiting for a bus.","explanation_kk":"Ол автобусты күтіп тұрғанда плакатты көрді.","explanation_en":"In the text: she saw the poster while she was waiting for a bus."},{"question":"What nearly stopped Dana from joining?","options":["She almost walked past the poster.","She did not own a camera.","The walk was in another city."],"correct":0,"explanation":"«Nearly walked past it» — она чуть не прошла мимо.","explanation_kk":"«Nearly walked past it» — ол мүмкіндікті елемей кете жаздады.","explanation_en":"“Nearly walked past it” — she almost walked by without noticing."},{"question":"What does “turning point” mean in this story?","options":["A difficult journey home","A small event that changed her direction","The place where the bus turned"],"correct":1,"explanation":"Этот вечер изменил то, как Дана проводит свободное время.","explanation_kk":"Бұл кеш Дананың бос уақытын және қаланы көру тәсілін өзгертті.","explanation_en":"That evening changed how Dana spends her free time."}]}'::jsonb, '00000000-0000-4000-8000-000000010401', '00000000-0000-4000-8000-000000000104', 1) on conflict do nothing;
insert into public.lessons (id, course_id, sort, summary, summary_kk, summary_en, minutes, is_free, is_published, title, title_kk, title_en) values ('00000000-0000-4000-8000-000000000105', '00000000-0000-4000-8000-000000000100', 105, 'Аудирование по TED-выступлению и шэдоуинг.', 'TED баяндамасы бойынша тыңдалым және шэдоуинг.', 'Listening to a TED talk and shadowing.', 12, false, false, 'A 30-day experiment', '30 күндік эксперимент', 'A 30-day experiment') on conflict do nothing;
insert into public.lesson_materials (lesson_id, video_url, body, body_kk, body_en) values ('00000000-0000-4000-8000-000000000105', 'https://www.youtube.com/watch?v=UNP03fDSj1U', '## Watch twice
Первый раз — для главной мысли. Второй — с субтитрами на английском, чтобы ответить на вопросы. Затем повторите ключевые фразы вслух за спикером.', '## Екі рет көріңіз
Бірінші рет — негізгі ой үшін. Екінші рет — сұрақтарға жауап беру үшін ағылшынша субтитрмен. Содан кейін негізгі сөйлемдерді спикерге ілесіп дауыстап қайталаңыз.', '## Watch twice
The first time — for the main idea. The second time — with English subtitles, to answer the questions. Then repeat the key phrases out loud after the speaker.') on conflict do nothing;
insert into public.tasks (kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data, id, lesson_id, sort) values ('quiz', 'Listening check', 'Listening check', 'Listening check', 'Ответьте после просмотра.', 'Көріп болғаннан кейін жауап беріңіз.', 'Answer after watching.', '{"questions":[{"question":"What is Matt’s main message?","options":["Change your whole life in one day.","Try one meaningful change consistently for 30 days.","Avoid difficult challenges."],"correct":1,"explanation":"30 дней — достаточно, чтобы попробовать новую привычку и заметить перемены.","explanation_kk":"Оның ойынша, жаңа әдетті байқап көруге және өзгерісті сезуге 30 күн жеткілікті.","explanation_en":"30 days is enough to try a new habit and notice a change."},{"question":"Which daily challenge made the month more memorable?","options":["Taking one photograph","Cycling up a mountain","Giving up all technology"],"correct":0,"explanation":"Он фотографировал каждый день и помнил, где был и что делал.","explanation_kk":"Ол күн сайын суретке түсіріп, сол күндері қайда және не істеп жүргенін есте сақтады.","explanation_en":"He took a photo every day and remembered where he was and what he was doing."},{"question":"What happened as his challenges became harder?","options":["He became less interested.","His self-confidence grew.","He stopped after one month."],"correct":1,"explanation":"Более сложные челленджи сделали его увереннее.","explanation_kk":"Күрделірек сынақтар оның сенімін арттырып, батылырақ болуына көмектесті.","explanation_en":"Harder challenges made him more confident."},{"question":"Which changes were more likely to ‘stick’?","options":["Small sustainable changes","Big crazy challenges","Changes suggested by other people"],"correct":0,"explanation":"Небольшие реалистичные изменения чаще становятся привычкой.","explanation_kk":"Жалғастыруға болатын шағын, тұрақты өзгерістер әдетке айналуы ықтимал болды.","explanation_en":"Small, realistic changes are more likely to become habits."}]}'::jsonb, '00000000-0000-4000-8000-000000010501', '00000000-0000-4000-8000-000000000105', 1) on conflict do nothing;
insert into public.tasks (kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data, id, lesson_id, sort) values ('pronunciation', 'Shadowing', 'Shadowing', 'Shadowing', 'Повторите ключевые фразы спикера с той же интонацией.', 'Спикердің негізгі сөйлемдерін сондай интонациямен қайталаңыз.', 'Repeat the speaker''s key phrases with the same intonation.', '{"phrases":[{"text":"I decided to try something new for 30 days.","hint":"Скажите на одном дыхании.","hint_kk":"Бір демде айтыңыз.","hint_en":"Say it in one breath."},{"text":"The months were much more memorable.","hint":"Ударение на MUCH и MEMorable.","hint_kk":"Екпін MUCH және MEMorable сөздеріне түседі.","hint_en":"The stress is on MUCH and MEMorable."}]}'::jsonb, '00000000-0000-4000-8000-000000010502', '00000000-0000-4000-8000-000000000105', 2) on conflict do nothing;
insert into public.lessons (id, course_id, sort, summary, summary_kk, summary_en, minutes, is_free, is_published, title, title_kk, title_en) values ('00000000-0000-4000-8000-000000000106', '00000000-0000-4000-8000-000000000100', 106, 'Рассказ на 60 секунд о первом опыте.', 'Алғашқы тәжірибе туралы 60 секундтық әңгіме.', 'A 60-second story about a first experience.', 10, false, false, 'Tell your story', 'Өз оқиғаңды айт', 'Tell your story') on conflict do nothing;
insert into public.lesson_materials (lesson_id, video_url, body, body_kk, body_en) values ('00000000-0000-4000-8000-000000000106', '', '## Your 60-second story
Расскажите о том, как вы что-то сделали впервые.
- **Set the scene** — где вы были, что делали?
- **Describe the moment** — что произошло, что вы почувствовали?
- **Reflect** — чему это вас научило?

Сначала потренируйте модельную историю ниже — преподаватель послушает и даст советы.', '## Your 60-second story
Бір нәрсені алғаш рет қалай жасағаныңыз туралы айтыңыз.
- **Set the scene** — қайда болдыңыз, не істеп жүрдіңіз?
- **Describe the moment** — не болды, не сезіндіңіз?
- **Reflect** — бұл сізге не үйретті?

Алдымен төмендегі үлгі әңгімені жаттықтырыңыз — оқытушы тыңдап, кеңес береді.', '## Your 60-second story
Tell us about a time you did something for the first time.
- **Set the scene** — where were you, what were you doing?
- **Describe the moment** — what happened, how did you feel?
- **Reflect** — what did it teach you?

First practise the model story below — a teacher will listen and give you tips.') on conflict do nothing;
insert into public.tasks (kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data, id, lesson_id, sort) values ('pronunciation', 'Модельная история', 'Үлгі әңгіме', 'Model story', 'Прочитайте историю по фразам.', 'Әңгімені сөйлем бойынша оқыңыз.', 'Read the story phrase by phrase.', '{"phrases":[{"text":"Last summer I was living in Almaty and working long hours."},{"text":"One day a friend invited me to a climbing class."},{"text":"I was terrified, but I reached the top of the wall."},{"text":"Now I know that fear is just the first step."}]}'::jsonb, '00000000-0000-4000-8000-000000010601', '00000000-0000-4000-8000-000000000106', 1) on conflict do nothing;
