insert into public.lesson_materials (lesson_id, video_url, body, body_kk, body_en) values ('00000000-0000-4000-8000-000000000108', '', '## Unit checkpoint
Короткий тест по грамматике, чтению и аудированию. Можно проходить сколько угодно раз — сохраняется лучший результат.', '## Unit checkpoint
Грамматика, оқу және тыңдалым бойынша қысқа тест. Қанша рет болса да өтуге болады — ең жақсы нәтиже сақталады.', '## Unit checkpoint
