insert into public.tasks (kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data, id, lesson_id, sort) values ('quiz', 'Unit check', 'Unit check', 'Unit check', '', '', '', '{"questions":[{"question":"I ___ home when I ___ an old friend.","options":["walked / was seeing","was walking / saw","was walking / was seeing"],"correct":1,"explanation":"Фоновое действие — past continuous, событие — past simple.","explanation_kk":"Ұзақ әрекетке past continuous, оны бөлген оқиғаға past simple қолданылады.","explanation_en":"Background action — past continuous; the event — past simple."},{"question":"What does “turning point” mean?","options":["A difficult journey home","A small event that changed someone''s direction","The place where the bus turned"],"correct":1},{"question":"Which changes are more likely to ‘stick’?","options":["Small sustainable changes","Big crazy challenges","Changes suggested by other people"],"correct":0}]}'::jsonb, '00000000-0000-4000-8000-000000010801', '00000000-0000-4000-8000-000000000108', 1) on conflict do nothing;

